# kube-pki: a small declarative x509 PKI for the NixOS kubernetes module.
#
#   init-ca   create (or import) the long-lived material that lives in the repo:
#             CA key + certificate, the service-account signing key, and a
#             long-lived admin kubeconfig for your workstation
#   ensure    issue / renew the per-component certificates described by a spec,
#             then restart the units that use what changed
#   status    show what `ensure` would do, without changing anything
#
# The spec is a JSON document generated by Nix from the kubernetes configuration
# (see the host.services.kubernetes-pki module). It only contains names, SANs and
# paths; the CA key and the service-account key are provided through sops-nix.

usage() {
  cat <<'USAGE'
Usage:
  kube-pki init-ca --out DIR --server https://HOST:6443 [--import DIR]
                   [--ca-cn CN] [--ca-days N] [--admin-cn CN] [--admin-days N]
                   [--cluster NAME]
  kube-pki ensure [--spec FILE] [--no-restart]
  kube-pki status [--spec FILE]

The spec defaults to $KUBE_PKI_SPEC, then to /etc/kubernetes/kube-pki-spec.json.
USAGE
}

log() { printf 'kube-pki: %s\n' "$*" >&2; }
die() {
  log "error: $*"
  exit 1
}

tmp=""
cleanup() { [ -n "$tmp" ] && rm -rf "$tmp"; }
trap cleanup EXIT

# ---------------------------------------------------------------------------
# x509 inspection helpers. Every function prints normalized, sorted lines so
# that the on-disk certificate can be compared to the spec with plain string
# equality.
# ---------------------------------------------------------------------------
pubkey_of_cert() { openssl x509 -in "$1" -noout -pubkey | openssl pkey -pubin -outform DER | sha256sum | cut -d' ' -f1; }
pubkey_of_key() { openssl pkey -in "$1" -pubout -outform DER | sha256sum | cut -d' ' -f1; }

subject_field() { # <cert> <CN|O>
  openssl x509 -in "$1" -noout -subject -nameopt sep_multiline,utf8,esc_ctrl |
    sed -n "s/^ *$2=//p" | sort
}

sans_of_cert() { # <cert>  -> lines "DNS:name" / "IP:addr"
  openssl x509 -in "$1" -noout -ext subjectAltName 2>/dev/null |
    tail -n +2 | tr ',' '\n' | sed -e 's/^ *//' -e 's/^IP Address:/IP:/' |
    grep -E '^(DNS|IP):' | sort || true
}

ekus_of_cert() { # <cert>  -> lines "server" / "client"
  openssl x509 -in "$1" -noout -ext extendedKeyUsage 2>/dev/null |
    tail -n +2 | tr ',' '\n' | sed -e 's/^ *//' \
      -e 's/^TLS Web Server Authentication$/server/' \
      -e 's/^TLS Web Client Authentication$/client/' |
    grep -Ex 'server|client' | sort || true
}

expected_sans() { # <cert-json>
  jq -r '((.dnsNames // []) | map("DNS:" + .)[]), ((.ipAddresses // []) | map("IP:" + .)[])' <<<"$1" | sort
}
expected_ekus() { jq -r '.usages[]' <<<"$1" | sort; }
expected_orgs() { jq -r '(.organizations // [])[]' <<<"$1" | sort; }

not_after() { openssl x509 -enddate -noout -in "$1" | cut -d= -f2; }

# install_file <src> <dst> <mode> <owner> <group>: atomic replace, ownership only
# when we are root and the account exists (so the tool also works in tests).
install_file() {
  local src=$1 dst=$2 mode=$3 owner=$4 group=$5
  local args=(-m "$mode")
  if [ "$(id -u)" = 0 ]; then
    if getent passwd "$owner" >/dev/null; then
      args+=(-o "$owner")
    else
      log "warning: user '$owner' does not exist, keeping root ownership of $dst"
    fi
    if getent group "$group" >/dev/null; then
      args+=(-g "$group")
    fi
  fi
  install "${args[@]}" -T "$src" "$dst.tmp"
  mv -f "$dst.tmp" "$dst"
}

# ---------------------------------------------------------------------------
# spec handling
# ---------------------------------------------------------------------------
spec_file=""
spec_json=""
dir=""
renew_before=""
validity_days=""
ca_cert_src=""
ca_key_src=""
sa_key_src=""
ca_cert=""

load_spec() {
  if [ -z "$spec_file" ]; then
    spec_file=${KUBE_PKI_SPEC:-/etc/kubernetes/kube-pki-spec.json}
  fi
  [ -r "$spec_file" ] || die "spec file '$spec_file' is not readable"
  spec_json=$(jq -c . "$spec_file") || die "spec file '$spec_file' is not valid JSON"
  dir=$(jq -r '.secretsDir' <<<"$spec_json")
  renew_before=$(jq -r '.renewBeforeSeconds' <<<"$spec_json")
  validity_days=$(jq -r '.validityDays' <<<"$spec_json")
  ca_cert_src=$(jq -r '.ca.certFile // empty' <<<"$spec_json")
  ca_key_src=$(jq -r '.ca.keyFile // empty' <<<"$spec_json")
  sa_key_src=$(jq -r '.serviceAccount.keyFile // empty' <<<"$spec_json")
  ca_cert="$dir/ca.pem"
  [ -n "$dir" ] && [ "$dir" != null ] || die "spec has no secretsDir"
}

cert_names() { jq -r '.certs | keys[]' <<<"$spec_json"; }
cert_spec() { jq -c --arg n "$1" '.certs[$n]' <<<"$spec_json"; }

# renewal_reason <name> <cert-json>: prints why the certificate must be
# (re)issued, or nothing when it matches the spec and is not about to expire.
renewal_reason() {
  local name=$1 c=$2 cert key
  cert="$dir/$name.pem"
  key="$dir/$name-key.pem"
  if [ ! -s "$cert" ] || [ ! -s "$key" ]; then
    echo "missing"
    return
  fi
  if ! openssl x509 -checkend "$renew_before" -noout -in "$cert" >/dev/null 2>&1; then
    echo "expires within the renewal window (not after $(not_after "$cert"))"
    return
  fi
  if ! openssl verify -CAfile "$ca_cert" "$cert" >/dev/null 2>&1; then
    echo "not valid under the current CA"
    return
  fi
  if [ ! -r "$key" ]; then
    echo "private key not readable (run as root)"
    return
  fi
  if [ "$(pubkey_of_cert "$cert")" != "$(pubkey_of_key "$key")" ]; then
    echo "private key does not match"
    return
  fi
  if [ "$(subject_field "$cert" CN)" != "$(jq -r '.cn' <<<"$c")" ]; then
    echo "common name changed"
    return
  fi
  if [ "$(subject_field "$cert" O)" != "$(expected_orgs "$c")" ]; then
    echo "organizations changed"
    return
  fi
  if [ "$(sans_of_cert "$cert")" != "$(expected_sans "$c")" ]; then
    echo "subject alternative names changed"
    return
  fi
  if [ "$(ekus_of_cert "$cert")" != "$(expected_ekus "$c")" ]; then
    echo "key usage changed"
    return
  fi
}

# issue_leaf <name> <cert-json>: new key + certificate signed by the CA.
issue_leaf() {
  local name=$1 c=$2 cn subj ext i o d a owner group
  cn=$(jq -r '.cn' <<<"$c")
  owner=$(jq -r '.owner' <<<"$c")
  group=$(jq -r '.group' <<<"$c")
  subj="/CN=${cn//\//\\/}"
  while IFS= read -r o; do
    [ -n "$o" ] && subj+="/O=${o//\//\\/}"
  done < <(jq -r '(.organizations // [])[]' <<<"$c")

  ext="$tmp/$name.cnf"
  {
    echo "[ leaf ]"
    echo "basicConstraints = critical, CA:FALSE"
    echo "keyUsage = critical, digitalSignature, keyEncipherment"
    echo "extendedKeyUsage = $(jq -r '.usages | map(if . == "server" then "serverAuth" else "clientAuth" end) | join(", ")' <<<"$c")"
    echo "subjectKeyIdentifier = hash"
    echo "authorityKeyIdentifier = keyid, issuer"
    if [ "$(jq -r '((.dnsNames // []) + (.ipAddresses // [])) | length' <<<"$c")" != 0 ]; then
      echo "subjectAltName = @alt"
      echo "[ alt ]"
      i=1
      while IFS= read -r d; do
        echo "DNS.$i = $d"
        i=$((i + 1))
      done < <(jq -r '(.dnsNames // [])[]' <<<"$c")
      i=1
      while IFS= read -r a; do
        echo "IP.$i = $a"
        i=$((i + 1))
      done < <(jq -r '(.ipAddresses // [])[]' <<<"$c")
    fi
  } >"$ext"

  openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out "$tmp/$name-key.pem" 2>/dev/null
  openssl req -new -key "$tmp/$name-key.pem" -subj "$subj" -out "$tmp/$name.csr"
  openssl x509 -req -in "$tmp/$name.csr" -CA "$ca_cert" -CAkey "$ca_key_src" \
    -set_serial "0x$(openssl rand -hex 16)" -days "$validity_days" -sha256 \
    -extfile "$ext" -extensions leaf -out "$tmp/$name.pem" 2>/dev/null
  install_file "$tmp/$name-key.pem" "$dir/$name-key.pem" 0600 "$owner" "$group"
  install_file "$tmp/$name.pem" "$dir/$name.pem" 0644 "$owner" "$group"
}

cmd_ensure() {
  local no_restart=0
  while [ $# -gt 0 ]; do
    case $1 in
      --spec) spec_file=$2; shift 2 ;;
      --no-restart) no_restart=1; shift ;;
      *) die "unknown argument for ensure: $1" ;;
    esac
  done
  load_spec
  [ "$(id -u)" = 0 ] || log "warning: not running as root, file ownership will not be set"

  [ -n "$ca_cert_src" ] && [ -s "$ca_cert_src" ] ||
    die "CA certificate not available (spec ca.certFile='${ca_cert_src:-<unset>}'). Bootstrap the PKI with 'kube-pki init-ca' first."
  [ -n "$ca_key_src" ] && [ -s "$ca_key_src" ] ||
    die "CA private key not available (spec ca.keyFile='${ca_key_src:-<unset>}'). Is the sops secret deployed?"
  [ -n "$sa_key_src" ] && [ -s "$sa_key_src" ] ||
    die "service-account signing key not available (spec serviceAccount.keyFile='${sa_key_src:-<unset>}'). Is the sops secret deployed?"
  [ "$(pubkey_of_cert "$ca_cert_src")" = "$(pubkey_of_key "$ca_key_src")" ] ||
    die "the CA private key does not match the CA certificate"
  if ! openssl x509 -checkend $((180 * 86400)) -noout -in "$ca_cert_src" >/dev/null; then
    log "WARNING: the CA certificate expires on $(not_after "$ca_cert_src"); plan a CA rotation (kube-pki init-ca)"
  fi

  [ -d "$dir" ] || install -d -m 0755 "$dir"
  exec 9>"$dir/.kube-pki.lock"
  flock 9
  tmp=$(mktemp -d)

  declare -A restart=()
  mark() {
    local u
    for u in "$@"; do restart["$u"]=1; done
  }
  local -a all_units sa_units
  mapfile -t all_units < <(jq -r '[(.certs[].restartUnits // [])[], (.serviceAccount.restartUnits // [])[]] | unique | .[]' <<<"$spec_json")
  mapfile -t sa_units < <(jq -r '(.serviceAccount.restartUnits // [])[]' <<<"$spec_json")

  # 1. the CA certificate (public): every component trusts it
  if ! cmp -s "$ca_cert_src" "$ca_cert"; then
    log "installing CA certificate to $ca_cert"
    install_file "$ca_cert_src" "$ca_cert" 0644 root root
    mark "${all_units[@]}"
  fi

  # 2. the service-account signing key and its public half
  local sa_owner sa_group sa_key sa_pub
  sa_owner=$(jq -r '.serviceAccount.owner // "root"' <<<"$spec_json")
  sa_group=$(jq -r '.serviceAccount.group // "root"' <<<"$spec_json")
  sa_key="$dir/service-account-key.pem"
  sa_pub="$dir/service-account.pem"
  if ! cmp -s "$sa_key_src" "$sa_key"; then
    log "installing service-account signing key to $sa_key"
    install_file "$sa_key_src" "$sa_key" 0600 "$sa_owner" "$sa_group"
    mark "${sa_units[@]}"
  fi
  openssl pkey -in "$sa_key_src" -pubout -out "$tmp/service-account.pub"
  if ! cmp -s "$tmp/service-account.pub" "$sa_pub"; then
    log "installing service-account public key to $sa_pub"
    install_file "$tmp/service-account.pub" "$sa_pub" 0644 "$sa_owner" "$sa_group"
    mark "${sa_units[@]}"
  fi

  # 3. every leaf certificate in the spec
  local name c reason
  local -a units
  while IFS= read -r name; do
    c=$(cert_spec "$name")
    reason=$(renewal_reason "$name" "$c")
    if [ -n "$reason" ]; then
      log "issuing $name: $reason"
      issue_leaf "$name" "$c"
      mapfile -t units < <(jq -r '(.restartUnits // [])[]' <<<"$c")
      [ ${#units[@]} -gt 0 ] && mark "${units[@]}"
    fi
  done < <(cert_names)

  # 4. restart whatever uses the files that changed. --no-block matters: at
  #    boot and on nixos-rebuild the dependents are ordered after this unit.
  if [ ${#restart[@]} -eq 0 ]; then
    log "all certificates are up to date"
    return
  fi
  local -a changed=("${!restart[@]}")
  if [ "$no_restart" = 1 ]; then
    log "changed files affect ${changed[*]} (restart skipped)"
  elif command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]; then
    log "restarting ${changed[*]}"
    systemctl --no-block try-restart "${changed[@]}" || log "warning: restarting some of ${changed[*]} failed, check them manually"
  else
    log "changed files affect ${changed[*]} (no systemd, nothing restarted)"
  fi
}

cmd_status() {
  while [ $# -gt 0 ]; do
    case $1 in
      --spec) spec_file=$2; shift 2 ;;
      *) die "unknown argument for status: $1" ;;
    esac
  done
  load_spec
  printf '%-34s %-26s %s\n' NAME 'NOT AFTER' STATE
  if [ -s "$ca_cert" ]; then
    printf '%-34s %-26s %s\n' ca "$(not_after "$ca_cert")" "$(if [ -n "$ca_cert_src" ] && cmp -s "$ca_cert_src" "$ca_cert"; then echo ok; else echo 'differs from spec source'; fi)"
  else
    printf '%-34s %-26s %s\n' ca - 'missing'
  fi
  local name c reason cert
  while IFS= read -r name; do
    c=$(cert_spec "$name")
    cert="$dir/$name.pem"
    reason=$(renewal_reason "$name" "$c")
    printf '%-34s %-26s %s\n' "$name" "$([ -s "$cert" ] && not_after "$cert" || echo -)" "${reason:-ok}"
  done < <(cert_names)
}

cmd_init_ca() {
  local out="" import="" server="" ca_cn="kubernetes-cluster-ca" ca_days=3650
  local admin_cn="cluster-admin" admin_days=1825 cluster="homelab"
  while [ $# -gt 0 ]; do
    case $1 in
      --out) out=$2; shift 2 ;;
      --import) import=$2; shift 2 ;;
      --server) server=$2; shift 2 ;;
      --ca-cn) ca_cn=$2; shift 2 ;;
      --ca-days) ca_days=$2; shift 2 ;;
      --admin-cn) admin_cn=$2; shift 2 ;;
      --admin-days) admin_days=$2; shift 2 ;;
      --cluster) cluster=$2; shift 2 ;;
      *) die "unknown argument for init-ca: $1" ;;
    esac
  done
  [ -n "$out" ] || die "--out DIR is required"
  [ -n "$server" ] || die "--server https://HOST:6443 is required (it goes into the admin kubeconfig)"
  umask 077
  mkdir -p "$out"
  tmp=$(mktemp -d)

  if [ -n "$import" ]; then
    [ -s "$import/ca.pem" ] && [ -s "$import/ca-key.pem" ] || die "--import DIR needs ca.pem and ca-key.pem"
    log "importing CA from $import"
    cp "$import/ca.pem" "$out/ca.pem"
    cp "$import/ca-key.pem" "$out/ca-key.pem"
    if [ -s "$import/service-account-key.pem" ]; then
      cp "$import/service-account-key.pem" "$out/service-account-key.pem"
    fi
    [ "$(pubkey_of_cert "$out/ca.pem")" = "$(pubkey_of_key "$out/ca-key.pem")" ] || die "imported CA key does not match the CA certificate"
  elif [ -s "$out/ca-key.pem" ] && [ -s "$out/ca.pem" ]; then
    log "keeping existing CA in $out"
  else
    log "creating CA '$ca_cn' valid for $ca_days days"
    openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:4096 -out "$out/ca-key.pem" 2>/dev/null
    openssl req -x509 -new -key "$out/ca-key.pem" -days "$ca_days" -sha256 \
      -subj "/CN=${ca_cn//\//\\/}/O=NixOS" \
      -addext "basicConstraints = critical, CA:TRUE" \
      -addext "keyUsage = critical, keyCertSign, cRLSign" \
      -addext "subjectKeyIdentifier = hash" \
      -out "$out/ca.pem"
  fi
  chmod 0644 "$out/ca.pem"

  if [ -s "$out/service-account-key.pem" ]; then
    log "keeping existing service-account signing key"
  else
    log "creating service-account signing key"
    openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out "$out/service-account-key.pem" 2>/dev/null
  fi

  log "creating admin client certificate '$admin_cn' (system:masters) valid for $admin_days days"
  openssl genpkey -algorithm RSA -pkeyopt rsa_keygen_bits:2048 -out "$out/admin-key.pem" 2>/dev/null
  openssl req -new -key "$out/admin-key.pem" -subj "/CN=${admin_cn//\//\\/}/O=system:masters" -out "$tmp/admin.csr"
  printf '%s\n' \
    'basicConstraints = critical, CA:FALSE' \
    'keyUsage = critical, digitalSignature, keyEncipherment' \
    'extendedKeyUsage = clientAuth' \
    'subjectKeyIdentifier = hash' \
    'authorityKeyIdentifier = keyid, issuer' >"$tmp/admin.cnf"
  openssl x509 -req -in "$tmp/admin.csr" -CA "$out/ca.pem" -CAkey "$out/ca-key.pem" \
    -set_serial "0x$(openssl rand -hex 16)" -days "$admin_days" -sha256 \
    -extfile "$tmp/admin.cnf" -out "$out/admin.pem" 2>/dev/null

  {
    echo "apiVersion: v1"
    echo "kind: Config"
    echo "clusters:"
    echo "- name: $cluster"
    echo "  cluster:"
    echo "    server: $server"
    echo "    certificate-authority-data: $(base64 -w0 "$out/ca.pem")"
    echo "users:"
    echo "- name: $admin_cn@$cluster"
    echo "  user:"
    echo "    client-certificate-data: $(base64 -w0 "$out/admin.pem")"
    echo "    client-key-data: $(base64 -w0 "$out/admin-key.pem")"
    echo "contexts:"
    echo "- name: $cluster"
    echo "  context:"
    echo "    cluster: $cluster"
    echo "    user: $admin_cn@$cluster"
    echo "current-context: $cluster"
  } >"$out/admin.kubeconfig"

  cat <<SUMMARY

Written to $out:
  ca.pem                   public CA certificate (commit as is)
  ca-key.pem               CA private key (commit sops-encrypted)
  service-account-key.pem  service-account signing key (commit sops-encrypted, never rotate casually)
  admin.pem, admin-key.pem long-lived cluster-admin client certificate
  admin.kubeconfig         ready-to-use kubeconfig for your workstation (commit sops-encrypted)

CA:    $(openssl x509 -subject -noout -in "$out/ca.pem" | sed 's/^subject=//'), not after $(not_after "$out/ca.pem")
Admin: not after $(not_after "$out/admin.pem")

Encrypt in place with sops once the files are at their final path, e.g.
  sops -e -i hosts/<host>/pki/ca-key.pem
SUMMARY
}

case ${1:-} in
  init-ca) shift; cmd_init_ca "$@" ;;
  ensure) shift; cmd_ensure "$@" ;;
  status) shift; cmd_status "$@" ;;
  -h | --help | help | "") usage ;;
  *) die "unknown command: $1 (try --help)" ;;
esac
